package keystrokesmod.client.ui.hud;

/**
 * Counts the clicks the game actually performs (not the physical mouse presses). The Minecraft
 * mixin calls {@link #leftClick()} / {@link #rightClick()} every time the game runs its own
 * left or right click, so clicks generated by the Left Clicker, Right Clicker or any other module
 * are counted exactly like real ones. Everything runs on the client thread.
 */
public final class ClickStats {
    private static final int RING = 64;
    private static final String[] NUMBERS = new String[100];

    static {
        for (int i = 0; i < NUMBERS.length; i++) NUMBERS[i] = Integer.toString(i);
    }

    private static final long[] LEFT = new long[RING];
    private static final long[] RIGHT = new long[RING];
    private static int leftPos;
    private static int rightPos;
    private static long leftTotal;
    private static long rightTotal;

    private ClickStats() {
    }

    public static void leftClick() {
        LEFT[leftPos] = System.currentTimeMillis();
        leftPos = (leftPos + 1) % RING;
        leftTotal++;
    }

    public static void rightClick() {
        RIGHT[rightPos] = System.currentTimeMillis();
        rightPos = (rightPos + 1) % RING;
        rightTotal++;
    }

    /** Total clicks since the game started; changes whenever a click happened. */
    public static long leftTotal() {
        return leftTotal;
    }

    public static long rightTotal() {
        return rightTotal;
    }

    public static int leftCps(long nowMs) {
        return count(LEFT, nowMs);
    }

    public static int rightCps(long nowMs) {
        return count(RIGHT, nowMs);
    }

    private static int count(long[] ring, long nowMs) {
        int n = 0;
        for (int i = 0; i < RING; i++) {
            if (nowMs - ring[i] < 1000L) n++;
        }
        return n;
    }

    /** Cached text for a small number, so drawing it allocates nothing. */
    public static String number(int n) {
        if (n < 0) return NUMBERS[0];
        return n < NUMBERS.length ? NUMBERS[n] : "99+";
    }
}
